  _push(`<div${ssrRenderAttrs(_attrs)}><div style="${ssrRenderStyle({ "display": "none" })}" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /api/gateway-endpoint-reference.md for this page in Markdown format</div><h1 id="gateway-endpoint-reference" tabindex="-1">Gateway endpoint reference <a class="header-anchor" href="#gateway-endpoint-reference" aria-label="Permalink to “Gateway endpoint reference”">​</a></h1>`);
